-- paperclip:migration-safety-ignore large-create-index-not-concurrently: Drizzle migrations run transactionally, so CONCURRENTLY is unavailable because this forward-only index backs the per-issue latest-activity ORDER BY created_at DESC LIMIT 1 probe that every issue-list sort keys on. Without it each probe re-reads one issue's full activity tail on a known-large table and dominates issue-list latency.
CREATE INDEX IF NOT EXISTS "activity_log_entity_issue_created_idx" ON "activity_log" USING btree ("company_id","entity_id","created_at" DESC NULLS LAST) WHERE "activity_log"."entity_type" = 'issue';
